#!/usr/bin/env bash
# Generated by fmverify. The local and CI paths run this same script, so a green pipeline
# means exactly what a green local run means.
#
# Invoke it as `bash ./verify.sh`. fmverify sets the executable bit when it generates on
# Linux or macOS, but it cannot on Windows -- so going through bash is what works either
# way, and every generated CI job does. `chmod +x` it if you would rather type ./verify.sh.
set -euo pipefail
cd "$(dirname "$0")"

# Microsoft.Z3 is not on nuget.org and .packages/ is not committed, so nothing restores
# until this has run. It verifies the package hash and refuses a mismatch.
bash ./fetch-solver.sh


# Build before the translation refresh: the audit warns when coverage evidence predates the target
# assembly, and on a clean run prove writes its evidence after this line.
dotnet build "CommunityToolkit.HighPerformance.Verification.slnx" -c Release

if [ -d "translation" ]; then
  # `..`, not `.`: this script has cd'd into the layer, and prove must inspect the target
  # repository. Pointed at the layer it finds only the layer's own projects, cannot tell which
  # is under verification, and refuses rather than guess (I-NO-GUESS).
  if command -v fmverify >/dev/null 2>&1 && [ -n "${FMTRANSLATOR:-}" ]; then
    # fmtranslator --backend=auto may emit .smt2 artifacts; the pinned CLI runs them.
    # An explicit Z3 path wins, so a preinstalled or locally pinned binary skips the fetch.
    if [ -z "${Z3:-}" ]; then
      bash ./fetch-z3.sh
    fi
    echo "== Translation proof gate =="
    fmverify prove .. --annotations=both
  else
    # The gate still checks the committed evidence; only the refresh is skipped.
    echo "translation/ present, but fmverify or FMTRANSLATOR is unavailable; checking committed evidence only." >&2
  fi
fi

echo "== Capability honesty check =="
# Non-zero here means an advertised capability class did not discharge. set -e stops us.
#
# --check, not the bare JSON emit: that refuses to serialise a ConformanceBacked property, because
# it cannot run your target and so cannot certify a claim about it -- which would take this script
# red for a layer that had earned one. And not --emit-trust-boundary either: that writes the file,
# and a verification step must not repair the staleness the gate is there to catch.
dotnet run --project "src/CommunityToolkit.HighPerformance.Spec.Descriptor" -c Release --no-build -- --check

# Hunts are excluded: they draw a fresh seed every run, so including them would make this script
# red on Tuesday and green on Wednesday -- and a conformance failure that comes and goes gets
# dismissed rather than investigated. Run them deliberately:
#   dotnet test "CommunityToolkit.HighPerformance.Verification.slnx" -c Release --filter Category=hunt
# Bridge coverage -- which of the target's annotations the run reached, and which cells of the
# model the encoding pinned -- is a fact about what the run reached rather than a verdict, so the
# gate never fails over it. Which means it never prints either: the gate reports failures, and a
# passing test's output is hidden at default verbosity. Naming a path here is what makes it visible
# on a green run.
export FMVERIFY_COVERAGE_OUT="$PWD/bridge-coverage.txt"

# Symbolic results are published by the same run: the JSON is the audit's input, the text file is
# the block printed below. Both are report-only, so an unwritable path never reddens the gate.
export FMVERIFY_SYMBOLIC_OUT="$PWD/symbolic-coverage.json"
export FMVERIFY_SYMBOLIC_TEXT_OUT="$PWD/symbolic-coverage.txt"

dotnet test "CommunityToolkit.HighPerformance.Verification.slnx" -c Release --no-build --filter "Category!=hunt"

# After the gate, because that is when the file exists. The gate writes it before its own assertion,
# so a red run leaves it on disk too -- but set -e stops us before here, and a red run has failures
# to read first.
if [ -f "$FMVERIFY_COVERAGE_OUT" ]; then
  echo
  echo "== Bridge coverage =="
  cat "$FMVERIFY_COVERAGE_OUT"
fi

if [ -f "$FMVERIFY_SYMBOLIC_TEXT_OUT" ]; then
  echo
  echo "== Symbolic coverage =="
  cat "$FMVERIFY_SYMBOLIC_TEXT_OUT"
fi
